
# Parse the salvage summary files generated by the pipeline.
# Each report looks like:
#   Sanger_Summary.2026-08-12_1048.txt
# and contains lines such as:
#   Salvage Metrics for ITS
#     0  samples were suitable to attempt salvaging (i.e.: had a good enough consensus to try).
#     0 samples were successfully salvaged and added to clusters.

# Set this to the project root or output directory that contains the Output_noise* folders.
data_dir <- "/Volumes/NCEA_work6/raw_data/Sanger_manuscript_benchmarking/4MARTINSEQUENCES/pipeline_validation_1/MycorrhizaTracer/"

# Find only benchmark summary files from Output_noiseX.YY directories.
# Ignore the plain Output directory because it is not a benchmark-noise run.
noise_dirs <- list.dirs(
  path = data_dir,
  recursive = FALSE,
  full.names = TRUE
)
noise_dirs <- noise_dirs[grepl("^Output_noise[0-9]+(?:\\.[0-9]+)?$", basename(noise_dirs))];noise_dirs

summary_files <- unlist(lapply(noise_dirs, function(noise_dir) {
  list.files(
    path = noise_dir,
    pattern = "^Sanger_Summary\\..+\\.txt$",
    full.names = TRUE
  )
}))

if (length(summary_files) == 0) {
  stop("No benchmark summary files found under Output_noise*. directories in: ", data_dir)
}

parse_summary_file <- function(summary_file) {
  lines <- readLines(summary_file, warn = FALSE)
  if (length(lines) == 0) {
    return(NULL)
  }

  summary_dir <- basename(dirname(summary_file))
  noise_level <- NA_real_
  if (grepl("^Output_noise", summary_dir)) {
    m <- regexec("^Output_noise([0-9]+(?:\\.[0-9]+)?)$", summary_dir)
    if (length(unlist(m)) > 0) {
      captured <- regmatches(summary_dir, m)[[1]][2]
      if (!is.na(captured) && nzchar(captured)) {
        noise_level <- as.numeric(captured)
      }
    }
  }

  gene <- NA_character_
  attempted <- NA_integer_
  successful <- NA_integer_
  rows <- list()

  for (line in lines) {
    if (grepl("^Salvage Metrics for", line)) {
      gene <- sub("^.*Salvage Metrics for\\s+", "", line)
      gene <- trimws(gene)
      next
    }

    if (is.na(gene) || !nzchar(gene)) {
      next
    }

    if (grepl("samples were suitable to attempt salvaging", line)) {
      attempted_match <- regexec("^\\s*([0-9]+)\\s+samples were suitable to attempt salvaging", line)
      attempted_val <- regmatches(line, attempted_match)[[1]][2]
      if (!is.na(attempted_val) && nzchar(attempted_val)) {
        attempted <- as.integer(attempted_val)
      }
      next
    }

    if (grepl("samples were successfully salvaged and added to clusters", line)) {
      successful_match <- regexec("^\\s*([0-9]+)\\s+samples were successfully salvaged and added to clusters", line)
      successful_val <- regmatches(line, successful_match)[[1]][2]
      if (!is.na(successful_val) && nzchar(successful_val)) {
        successful <- as.integer(successful_val)
      }

      if (!is.na(attempted) && !is.na(successful)) {
        rows[[length(rows) + 1L]] <- data.frame(
          summary_file = summary_file,
          summary_dir = summary_dir,
          noise_level = noise_level,
          gene = gene,
          samples_attempted = attempted,
          samples_successfully_salvaged = successful,
          stringsAsFactors = FALSE
        )
      }

      gene <- NA_character_
      attempted <- NA_integer_
      successful <- NA_integer_
    }
  }

  if (length(rows) == 0) {
    return(NULL)
  }

  do.call(rbind, rows)
}

salvage_summary_df <- do.call(
  rbind,
  lapply(summary_files, parse_summary_file)
)

if (is.null(salvage_summary_df)) {
  stop("No salvage summary rows were parsed from the summary files.")
}

salvage_summary_df$noise_level <- as.numeric(salvage_summary_df$noise_level)
salvage_summary_df$samples_attempted <- as.integer(salvage_summary_df$samples_attempted)
salvage_summary_df$samples_successfully_salvaged <- as.integer(salvage_summary_df$samples_successfully_salvaged)

str(salvage_summary_df)

# Summarize counts by noise level for a stacked barplot.
# If there are multiple summary files for the same noise level, use the latest one
# by sorting on the file name and then taking the last row per noise level.
plot_df <- salvage_summary_df[order(salvage_summary_df$noise_level, salvage_summary_df$summary_file), , drop = FALSE]
plot_df <- plot_df[!duplicated(plot_df$noise_level, fromLast = TRUE), , drop = FALSE]
plot_df <- plot_df[order(plot_df$noise_level), , drop = FALSE]

barplot(
  height = rbind(
    plot_df$samples_successfully_salvaged,
    pmax(0, plot_df$samples_attempted - plot_df$samples_successfully_salvaged)
  ),
  beside = FALSE,
  col = c("steelblue", "darkorange"),
  names.arg = sprintf("%.2f", plot_df$noise_level),
  xlab = "Noise level",
  ylab = "Count of samples",
  main = "Salvage outcomes by benchmark noise level",
  border = NA,
  legend.text = c("Successfully salvaged", "Attempted salvaging, but failed"),
  args.legend = list(x = "topleft", bty = "n", cex=2)
)
